import { getPlatform } from '@/config/platformUrls'

/**
 * Link that opens a project in 3DSpace (the 3DSpace navigator page for the object),
 * or '' when the 3DSpace URL is not resolved yet or the project has no id.
 */
export function projectSpaceUrl(projectId: string): string {
  const spaceUrl = getPlatform().spaceUrl
  if (!spaceUrl || !projectId) return ''
  return `${spaceUrl}/common/emxNavigator.jsp?objectId=${encodeURIComponent(projectId)}`
}
